function attachStarOcc(mat) {
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uOcc = OCC_U.dirs;
    sh.uniforms.uOccS = OCC_U.soft;
    sh.uniforms.uOccN = OCC_U.n;
    sh.vertexShader = 'uniform vec4 uOcc[12];\nuniform float uOccS[12];\nuniform int uOccN;\n' + sh.vertexShader;
    sh.vertexShader = sh.vertexShader.replace('#include <project_vertex>', [
      '#include <project_vertex>',
      '  float occVis = 1.0;',
      '  vec3 sdir = normalize(position);',
      '  for (int oi = 0; oi < 12; oi++) {',
      '    if (oi >= uOccN) break;',
      '    float ot = (dot(sdir, uOcc[oi].xyz) - uOcc[oi].w) / max(uOccS[oi], 1e-4);',
      '    occVis *= 1.0 - smoothstep(-1.0, 1.0, ot);',
      '  }',
      '  if (occVis < 0.5) gl_Position = vec4(2.0, 2.0, 2.0, 1.0);'
    ].join('\n'));
  };
  mat.customProgramCacheKey = () => 'starOcc_v1';
}
