      'varying vec3 vSunNormal;',
      'varying vec3 vSunView;',
      'void main() {',
      '  vSunDir = normalize(position);',
      '  vSunNormal = normalize(normalMatrix * normal);',
      '  vec4 vp = modelViewMatrix * vec4(position, 1.0);',
      '  vSunView = -vp.xyz;',
