    /* 对话 43：Ψ_local = Ψ_0 + k·(Ψ_A − Ψ_0)。sampleMSArr 复用 _sm 数组，
       必须先把 A=0 基线存下来再取星球级，否则前三个值会被覆盖 */
    const q = sampleMSArr(msFinal0, hi, muSi);
    const q0 = q[0], q1 = q[1], q2 = q[2];
    const p = sampleMSArr(msFinal, hi, muSi);
    const ps0 = q0 + (p[0] - q0) * localK;
    const ps1 = q1 + (p[1] - q1) * localK;
    const ps2 = q2 + (p[2] - q2) * localK;
    const scR = br[0] * dR, scG = br[1] * dR, scB = br[2] * dR, sm = bms * dM;
    Lr += Tr * ((scR * phR + sm * phM) * ts[0] + (scR + sm) * ps0) * seg;
    Lg += Tg * ((scG * phR + sm * phM) * ts[1] + (scG + sm) * ps1) * seg;
    Lb += Tb * ((scB * phR + sm * phM) * ts[2] + (scB + sm) * ps2) * seg;
