  _mnV.copy(MOON.pos).sub(EARTH.pos).normalize();
  skyMat.uniforms.uMoonDirW.value.copy(_mnV);
  U.uMoonDir.value.copy(_mnV).applyMatrix3(WORLDTOEF_M3).normalize();
