    '    float tm = (tEnter + tExit) * 0.5;',
    '    vec3 p = ro + dir * tm;',
    '    float r = length(p);',
    '    vec3 pdir = p / r;',
    '    vec3 Ts = atmoTransToSun(r, dot(pdir, uSunDirW));',
