    '               + (cell2 - 0.5) * 0.16 * uLowCellK;',
    '    float a = smoothstep(0.24 - uLowThr * uLowK + erode, 0.58 - uLowThr * uLowK + erode, covS)',
    '            * mix(0.82, 0.82 - 0.30 * uLowThin, uLowCellK);',
    '    vec3 colB = uCTint * vec3(1.02, 0.99, 0.95) * Ts * (0.34 + 0.72 * dayK) + amb;',
    '    colB *= 0.86 + 0.28 * cn1 - 0.10 * (street - 0.5) * uLowK;',
    '    premul = mix(premul, colB * a, farK);',
    '    alpha = mix(alpha, a, farK);',
    '    if (CDBG > 0.5 && CDBG < 1.5) { gl_FragColor = vec4(vec3(cov), 1.0); return; }',
    '    if (CDBG > 1.5 && CDBG < 2.5) { gl_FragColor = vec4(vec3(a), 1.0); return; }',
    '  }',
    '  float gateOut = mix(covGate, 1.0, farK * uLowK);',
    '  alpha *= gateOut; premul *= gateOut;',
    '  if (CDBG > 4.5) { gl_FragColor = vec4(vec3(alpha), 1.0); return; }',
    '  if (alpha < 0.004) { gl_FragColor = vec4(0.0); return; }',
