    '  vec3 apT;',
    '  float apDist = max((tEnter + tExit) * 0.5, 0.0);',
    '  vec3 apIn = atmoMarch(ro, dir, apDist, apT);',
    '  premul = premul * apT + apIn * alpha;',
    '  gl_FragColor = vec4(premul, alpha);',
    '  #include <tonemapping_fragment>',
    '  #include <colorspace_fragment>',
