  NEB.nearRequest = (NEB.nearRequest || 0) + 1;
  if (NEB.active == null) return;
  if (NEB.sprite) NEB.sprite.visible = false;
  NEB.group.visible = false;
  if (NEB.nearTex) {
    if (nebVolMat.uniforms.uTex.value === NEB.nearTex) nebVolMat.uniforms.uTex.value = null;
    NEB.nearTex.dispose();
    NEB.nearTex = null;
  }
  NEB.active = null;
  CINE_VOLUME.type=null; CINE_ASSETS?.cancel();
  updateCinematicStatus();
  document.body.classList.remove('nebula-view');
  NEB.canVol = false;
  NEB.idx = -1;
  NEB.body = null;
