  nebVolMat.uniforms.uTanY.value.copy(ty);
  NEB.tanX = tx; NEB.tanY = ty;

  journeyStop(true); FLY.on = false; MOM.v = 0; TW.a = null;
  GALAXY_BRIDGE.returnPose = null;
  cam.focus = NEB.body; cam.shift.set(0, 0, 0);
  cam.dir.copy(dir);
  cam.alt = clamp(R * (CINE_VOLUME.on?1.35:2.2), 2e10, 2.6e12);
  cam.yaw = 0; cam.pitch = -Math.PI / 2;
  NEB.group.visible=false;
  if(NEB.mainVolume){ scene.remove(NEB.mainVolume); NEB.mainVolume.material.dispose(); }
  const kind=nb.shape===1?7:nb.shape===2?8:nb.shape===3?9:nb.shape===4?10:nb.shape===5?11:nb.shape===6?12:6;
  NEB.mainVolume=MAIN_VOLUMES.create(kind,idx*7919+17,nb.c,{gain:1.0,m16Lod:kind===9 && nb.nearPhoto==='gc_heic0506b'});
  const fallback = NEB.mainVolume;
  const spec = compareId && compareId === nb.compareId ? {id:compareId} : nebulaFieldSpec(nb);
