  const objects = (window.__ORBIT_INLINE__ || {}).objects || [];
  if (!window.OrbitPackedHD) objects.forEach(o => { if (o.type && o.type.indexOf('galaxy') === 0 && o.photoKey) keys.add(o.photoKey); });
