      const imageId=own||'m87-eht',packed=window.__ORBIT_INLINE__||{},meta=(packed.atlasPhotoMeta||{})[imageId];
      imgKey='';imgFallback='';img=packed.atlasPhotos&&packed.atlasPhotos[imageId]?'data:image/jpeg;base64,'+packed.atlasPhotos[imageId]
        :(window.__ORBIT_ASSET_BASE__||(location.protocol==='file:'?'./public/data/':'./data/'))+'atlas-photos/'+imageId+'.jpg';
      src=(own?'本目标EHT射电观测重建影像':'M87* EHT观测影像参照，非本目标实拍')+'；'+(meta?meta.credit:'EHT Collaboration')+'。射电强度伪彩，不是可见光照片或三维扫描；质量为文献值。';
