    let manifest,buffer;
    if(packed&&packed.data){manifest=packed.manifest;const bytes=atob(packed.data);buffer=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)buffer[i]=bytes.charCodeAt(i);buffer=buffer.buffer;}
