    uShadowOn: _tu.uShadowOn, uShadowTexel: _tu.uShadowTexel,
    /* 对话 68：与地形共享近级联 uniform 对象 */
    uShadowMapN: _tu.uShadowMapN, uShadowMatN: _tu.uShadowMatN,
    uShadowTexelN: _tu.uShadowTexelN, uShadowSplit: _tu.uShadowSplit,
