      'attribute vec2 aLean;',
      'attribute float aPart;',
      'uniform float uTime;',
      'uniform float uLean;',
      'uniform float uType;',
      'uniform vec3 uCamEf;',
      'varying vec3 vWorldPos;',
      'varying vec3 vN;',
      'varying vec3 vUp;',
      'varying float vVar;',
      'varying float vPart;',
      'varying float vY;',
      'varying float vD;',
      'void main() {',
      '  vec3 lp = position;',
      /* 风摆：越靠上摆幅越大，岩石不摆 */
