      '  float ca = cos(la), sa = sin(la);',
      '  vec2 ld = vec2(aLean.x * ca - aLean.y * sa, aLean.x * sa + aLean.y * ca);',
      '  float leanAmt = pow(clamp(lp.y, 0.0, 1.0), 1.35) * 0.50 * isGrass * uLean;',
