    GLOBE_DRAG.body = pickGlobe(e.clientX, e.clientY);
    GLOBE_DRAG.lastT = performance.now();
    GLOBE_DRAG.moved = 0;
    if (GLOBE_DRAG.body) {
      GLOBE_DRAG.body.gVy = 0; GLOBE_DRAG.body.gVp = 0;
      GEST.globeGrabs = (GEST.globeGrabs || 0) + 1;
    }
