  _ptrs.delete(e.pointerId);
  if (_ptrs.size < 2) { _pinchD = 0; _pinchLadder = false; }
  /* 对话 111：全部抬手时把捏合的瞬时速度交给惯性继续滑行。
     衰减按「停手到抬手」的时长：快速甩出去有惯性，捏住想一会儿再松手就没有。
     已经交棒给 ZOOM / 推镜的手势不再给速度，否则会连锁触发下一次转场。 */
  if (_ptrs.size === 0 && _pinchActive) {
    const age = (performance.now() - _pinchT) / 1000;
    if (!_pinchHandoff && !FLY.on && !TW.busy) {
      momSetPinch(_pinchV * Math.exp(-age / 0.20));
    }
    _pinchActive = false; _pinchV = 0;
  }
  if (_ptrs.size === 0) {
    /* 松手时如果已经停住不动了，就别把旧速度交给惯性（否则球会自己滑走） */
    if (GLOBE_DRAG.body && performance.now() - GLOBE_DRAG.lastT > 140) {
      GLOBE_DRAG.body.gVy = 0; GLOBE_DRAG.body.gVp = 0;
    }
    dragging = false; GLOBE_DRAG.body = null;
  }
  else if (_ptrs.size === 1) {
    /* 双指里抬起一根：剩下那根要能立刻继续旋转（否则手感是「断一下」） */
    const p = _ptrs.values().next().value;
    dragging = true; lastX = p.x; lastY = p.y; _tapT = 0;
  }
