    const now = performance.now();
    GEST.lastMoved = +moved.toFixed(1); GEST.lastGap = Math.round(now - _tapT);
    GEST.lastDist = +Math.hypot(_tapX - _tapPX, _tapY - _tapPY).toFixed(1);
