    const mx = (p[0].x + p[1].x) * 0.5, my = (p[0].y + p[1].y) * 0.5;
    if (CS.active) {
      CS.theta -= (mx - _pinchMidX) * 0.0030 * SET.sens;
      CS.phi = clamp(CS.phi + (my - _pinchMidY) * 0.0026 * SET.sens * (SET.invertY ? -1 : 1), -1.45, 1.45);
    } else if (!orbitFocusedNebula(mx - _pinchMidX, my - _pinchMidY)) {
      cam.yaw -= (mx - _pinchMidX) * 0.0026 * SET.sens;
      cam.pitch = clamp(cam.pitch - (my - _pinchMidY) * 0.0022 * SET.sens * (SET.invertY ? -1 : 1), -1.52, 1.52);
    }
