    restore('postprocess', () => { _post.noMsaa = previousNoMsaa; postDispose(); });
    /* 先恢复逻辑尺寸再恢复 DPR，避免临时分配导出尺寸乘高 DPR 的巨大缓冲区。 */
    restore('size', () => renderer.setSize(sz.x, sz.y, false));
    restore('pixelRatio', () => renderer.setPixelRatio(prevPR));
    restore('canvasStyle', () => { el.style.width = cssW; el.style.height = cssH; });
    restore('viewport', () => renderer.setViewport(viewport));
    restore('scissor', () => renderer.setScissor(scissor));
    restore('scissorTest', () => renderer.setScissorTest(scissorTest));
    restore('camera', () => { camera.aspect = camA; camera.updateProjectionMatrix(); });
    restore('cosmicCamera', () => {
      if (CS.cam && csA !== null) { CS.cam.aspect = csA; CS.cam.updateProjectionMatrix(); }
    });
    for (const pair of refs) restore('aspectUniform', () => { pair[0].value = pair[1]; });
