        buffer: [gl.drawingBufferWidth, gl.drawingBufferHeight], css: [el.style.width, el.style.height],
        pixelRatio: renderer.getPixelRatio(), viewport: renderer.getViewport(new THREE.Vector4()).toArray(),
        scissor: renderer.getScissor(new THREE.Vector4()).toArray(), scissorTest: renderer.getScissorTest(),
        cameraAspect: camera.aspect, cosmicAspect: CS.cam ? CS.cam.aspect : null,
        aspects: refs.map(pair => pair[0].value), terrainPixelAngle: terrainMat.uniforms.uPixAng.value,
        noMsaa: _post.noMsaa, autoClear: renderer.autoClear,
        targetIsDefault: renderer.getRenderTarget() === null, contextLost: gl.isContextLost()
